Config for **EmpireAI** in **production**:

```json
{
  "source": {
    "repo": "empireaios/EmpireAI",
    "branch": "main",
    "checkSuites": true
  },
  "networking": {
    "serviceDomains": {
      "empireai-production.up.railway.app": {
        "port": 8080
      }
    },
    "privateNetworkEndpoint": "empireai"
  },
  "build": {
    "builder": "RAILPACK",
    "buildEnvironment": "V3"
  },
  "deploy": {
    "useLegacyStacker": false,
    "ipv6EgressEnabled": false,
    "runtime": "V2",
    "multiRegionConfig": {
      "sfo": {
        "numReplicas": 1
      }
    }
  },
  "volumeMounts": {
    "40ab30d1-2759-4eba-b3c8-255436610bb0": {
      "mountPath": "/data"
    }
  }
}
```

